const config = $('Workflow Settings').first().json;
const nowMs = Date.now();

const firstHours = Number(config.firstReminderHours);
const finalHours = Number(config.finalReminderHours);
const catchupMs = Number(config.reminderCatchupMinutes) * 60 * 1000;
const timeZone = String(config.businessTimezone || 'UTC');
const locale = String(config.locale || 'en-US');
const businessName = String(config.businessName || 'our team');

function getLine(description, labels) {
  const escaped = labels.map((x) => x.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|');
  const match = String(description || '').match(
    new RegExp('(?:^|\\n)\\s*(?:' + escaped + ')\\s*:\\s*(.+?)\\s*(?:\\n|$)', 'i')
  );
  return match ? match[1].trim() : '';
}

function normalizePhone(raw) {
  const value = String(raw || '').trim();
  if (!value) return '';
  const hasPlus = value.startsWith('+');
  const digits = value.replace(/\D/g, '');
  return hasPlus && digits.length >= 8 && digits.length <= 15 ? '+' + digits : '';
}

function appointmentCode(eventId, startIso) {
  const source = String(eventId || '') + '|' + String(startIso || '');
  let hash = 2166136261;
  for (let i = 0; i < source.length; i++) {
    hash ^= source.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).toUpperCase().padStart(8, '0');
}

function formatDate(startMs) {
  try {
    return new Intl.DateTimeFormat(locale, {
      timeZone,
      weekday: 'short',
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    }).format(new Date(startMs));
  } catch (error) {
    return new Date(startMs).toISOString().slice(0, 10);
  }
}

function formatTime(startMs) {
  try {
    return new Intl.DateTimeFormat(locale, {
      timeZone,
      hour: '2-digit',
      minute: '2-digit',
    }).format(new Date(startMs));
  } catch (error) {
    return new Date(startMs).toISOString().slice(11, 16) + ' UTC';
  }
}

return $input.all().map((item) => {
  const event = item.json || {};
  const description = String(event.description || '');
  const startIso = event.start && event.start.dateTime ? event.start.dateTime : '';
  const startMs = Date.parse(startIso);
  const statusMatch = description.match(/\[SENT_STATUS:([A-Z_]+)\]/i);
  const appointmentState = statusMatch ? statusMatch[1].toUpperCase() : 'UNCONFIRMED';

  const rawPhone = getLine(description, ['Phone']);
  const phone = normalizePhone(rawPhone);
  const customerName = getLine(description, ['Customer', 'Client', 'Name']) || 'there';
  const code = appointmentCode(event.id, startIso);

  let shouldSend = false;
  let stage = '';
  let skipReason = '';

  if (event.status === 'cancelled') {
    skipReason = 'calendar_event_cancelled';
  } else if (!startIso || Number.isNaN(startMs)) {
    skipReason = 'all_day_or_missing_start_time';
  } else if (!phone) {
    skipReason = 'missing_or_invalid_e164_phone';
  } else {
    const msUntilStart = startMs - nowMs;
    const dueStages = [
      { stage: 'FIRST', target: firstHours * 60 * 60 * 1000 },
      { stage: 'FINAL', target: finalHours * 60 * 60 * 1000 },
    ]
      .filter((entry) => (
        msUntilStart > 0 &&
        msUntilStart <= entry.target &&
        msUntilStart > entry.target - catchupMs
      ))
      .sort((a, b) => a.target - b.target);

    if (!dueStages.length) {
      skipReason = 'outside_reminder_window';
    } else {
      stage = dueStages[0].stage;

      if (appointmentState === 'RESCHEDULE_REQUESTED') {
        skipReason = 'appointment_reschedule_requested';
      } else if (stage === 'FINAL' && appointmentState === 'CONFIRMED') {
        skipReason = 'appointment_confirmed';
      } else {
        shouldSend = true;
      }
    }
  }

  const appointmentName = String(event.summary || 'your appointment');
  const location = String(event.location || '').trim();
  const reminderContext = stage === 'FINAL'
    ? 'about ' + finalHours + ' hour' + (finalHours === 1 ? '' : 's') + ' away'
    : 'about ' + firstHours + ' hour' + (firstHours === 1 ? '' : 's') + ' away';

  const rawIdempotency = 'appt_' + String(event.id || 'event') + '_' + startIso + '_' + (stage || 'none');
  const idempotencyKey = rawIdempotency.replace(/[^A-Za-z0-9_-]/g, '_').slice(0, 255);

  const appointmentDate = Number.isNaN(startMs) ? '' : formatDate(startMs);
  const appointmentTime = Number.isNaN(startMs) ? '' : formatTime(startMs);

  return {
    json: {
      shouldSend,
      skipReason,
      stage,
      eventId: String(event.id || ''),
      appointmentCode: code,
      eventStatus: String(event.status || ''),
      appointmentState,
      phone,
      customerName,
      appointmentName,
      appointmentStart: startIso,
      appointmentDate,
      appointmentTime,
      location,
      idempotencyKey,
      templateParameters: {
        customer_name: customerName,
        business_name: businessName,
        appointment_name: appointmentName,
        reminder_context: reminderContext,
        appointment_date: appointmentDate,
        appointment_time: appointmentTime,
        location_line: location ? ' Location: ' + location + '.' : '',
        reply_instruction: 'Reply CONFIRM ' + code + ' to confirm or RESCHEDULE ' + code + ' if you need another time.',
      },
    },
  };
});

const payload = $json.payload || {};
const text = String(payload.text || '').trim();
const normalized = text.toUpperCase().replace(/\s+/g, ' ').trim();

let replyAction = 'OTHER';
let replyCode = '';

if (/^(STOP|UNSUBSCRIBE|END|CANCEL|QUIT)\b/.test(normalized)) {
  replyAction = 'OPTOUT';
} else {
  const confirm = normalized.match(/^(CONFIRM|I CONFIRM|YES|Y)(?:\s+([A-F0-9]{8}))?$/);
  const reschedule = normalized.match(/^(RESCHEDULE|CHANGE)(?:\s+([A-F0-9]{8}))?$/);

  if (confirm) {
    replyAction = 'CONFIRM';
    replyCode = String(confirm[2] || '');
  } else if (reschedule) {
    replyAction = 'RESCHEDULE';
    replyCode = String(reschedule[2] || '');
  }
}

const senderPhone = String(payload.from || '').trim();
const rawChannel = String(payload.channel || '').toLowerCase();
const replyChannel = ['sms', 'whatsapp', 'rcs'].includes(rawChannel) ? rawChannel : '';
const sourceKey = String(
  $json.idempotencyKey ||
  (senderPhone + '_' + String(payload.received_at || $json.timestamp || '') + '_' + text)
);
const replyKeyBase = ('reply_' + sourceKey)
  .replace(/[^A-Za-z0-9_-]/g, '_')
  .slice(0, 220);

return [{
  json: {
    ...$json,
    replyText: text,
    replyAction,
    replyCode,
    isOptOutKeyword: replyAction === 'OPTOUT',
    senderPhone,
    replyChannel,
    replyKeyBase,
  },
}];

const context = $('Parse Customer Reply').first().json;
const config = $('Workflow Settings').first().json;
const nowMs = Date.now();
const timeZone = String(config.businessTimezone || 'UTC');
const locale = String(config.locale || 'en-US');

function getLine(description, labels) {
  const escaped = labels.map((x) => x.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|');
  const match = String(description || '').match(
    new RegExp('(?:^|\\n)\\s*(?:' + escaped + ')\\s*:\\s*(.+?)\\s*(?:\\n|$)', 'i')
  );
  return match ? match[1].trim() : '';
}

function normalizePhone(raw) {
  const value = String(raw || '').trim();
  const hasPlus = value.startsWith('+');
  const digits = value.replace(/\D/g, '');
  return hasPlus && digits.length >= 8 && digits.length <= 15 ? '+' + digits : '';
}

function appointmentCode(eventId, startIso) {
  const source = String(eventId || '') + '|' + String(startIso || '');
  let hash = 2166136261;
  for (let i = 0; i < source.length; i++) {
    hash ^= source.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).toUpperCase().padStart(8, '0');
}

function formatDate(startMs) {
  try {
    return new Intl.DateTimeFormat(locale, {
      timeZone,
      weekday: 'short',
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    }).format(new Date(startMs));
  } catch (error) {
    return new Date(startMs).toISOString().slice(0, 10);
  }
}

function formatTime(startMs) {
  try {
    return new Intl.DateTimeFormat(locale, {
      timeZone,
      hour: '2-digit',
      minute: '2-digit',
    }).format(new Date(startMs));
  } catch (error) {
    return new Date(startMs).toISOString().slice(11, 16) + ' UTC';
  }
}

function currentReplyKey(description) {
  const match = String(description || '').match(/\[SENT_LAST_REPLY_KEY:([A-Za-z0-9_-]+)\]/i);
  return match ? match[1] : '';
}

function currentStatus(description) {
  const match = String(description || '').match(/\[SENT_STATUS:([A-Z_]+)\]/i);
  return match ? match[1].toUpperCase() : '';
}

function descriptionWithStatus(description, status) {
  const original = String(description || '');
  if (currentReplyKey(original) === context.replyKeyBase && currentStatus(original) === status) {
    return original;
  }

  const cleaned = original
    .replace(/\n?\[SENT_STATUS:[^\]]+\]/gi, '')
    .replace(/\n?\[SENT_LAST_REPLY_AT:[^\]]+\]/gi, '')
    .replace(/\n?\[SENT_LAST_REPLY_CHANNEL:[^\]]+\]/gi, '')
    .replace(/\n?\[SENT_LAST_REPLY_KEY:[^\]]+\]/gi, '')
    .trim();

  return [
    cleaned,
    '[SENT_STATUS:' + status + ']',
    '[SENT_LAST_REPLY_AT:' + new Date().toISOString() + ']',
    '[SENT_LAST_REPLY_CHANNEL:' + context.replyChannel + ']',
    '[SENT_LAST_REPLY_KEY:' + context.replyKeyBase + ']',
  ].filter(Boolean).join('\n');
}

const sender = normalizePhone(context.senderPhone);
const phoneMatches = $input.all()
  .map((item) => item.json || {})
  .filter((event) => event.id && event.status !== 'cancelled' && event.start && event.start.dateTime)
  .map((event) => {
    const phone = normalizePhone(getLine(event.description, ['Phone']));
    const startIso = event.start.dateTime;
    const startMs = Date.parse(startIso);
    return {
      event,
      phone,
      startMs,
      code: appointmentCode(event.id, startIso),
    };
  })
  .filter((entry) => entry.phone && entry.phone === sender && !Number.isNaN(entry.startMs))
  .filter((entry) => entry.startMs >= nowMs)
  .sort((a, b) => a.startMs - b.startMs);

let candidates = phoneMatches;

if (context.replyCode) {
  candidates = phoneMatches.filter(
    (entry) => entry.code === String(context.replyCode).toUpperCase()
  );
}

let matchIssue = '';
if (candidates.length === 0) {
  matchIssue = context.replyCode ? 'reference_not_found' : 'no_phone_match';
} else if (!context.replyCode && candidates.length > 1) {
  matchIssue = 'ambiguous_multiple_appointments';
}

if (matchIssue) {
  return [{
    json: {
      appointmentFound: false,
      matchIssue,
      shouldReplyMatchIssue: matchIssue !== 'no_phone_match',
      candidateCodes: phoneMatches.slice(0, 5).map((entry) => entry.code),
      senderPhone: context.senderPhone,
      replyAction: context.replyAction,
      replyCode: context.replyCode,
      replyChannel: context.replyChannel,
      replyKeyBase: context.replyKeyBase,
    },
  }];
}

const selected = candidates[0];
const event = selected.event;
const description = String(event.description || '');
const customerName = getLine(description, ['Customer', 'Client', 'Name']);

return [{
  json: {
    appointmentFound: true,
    matchIssue: '',
    shouldReplyMatchIssue: false,
    eventId: String(event.id),
    appointmentCode: selected.code,
    customerName,
    appointmentName: String(event.summary || 'your appointment'),
    appointmentDate: formatDate(selected.startMs),
    appointmentTime: formatTime(selected.startMs),
    replyAction: context.replyAction,
    replyCode: context.replyCode,
    replyChannel: context.replyChannel,
    senderPhone: context.senderPhone,
    replyKeyBase: context.replyKeyBase,
    confirmedDescription: descriptionWithStatus(description, 'CONFIRMED'),
    rescheduleDescription: descriptionWithStatus(description, 'RESCHEDULE_REQUESTED'),
  },
}];

const config = $json;
const errors = [];

function text(value) {
  return String(value == null ? '' : value).trim();
}

function looksLikePlaceholder(value) {
  const v = text(value);
  return !v || /YOUR_|YOUR-|example\.com|^Your Business$/i.test(v);
}

if (looksLikePlaceholder(config.calendarId)) {
  errors.push('Set calendarId to the Google Calendar ID that contains the appointments.');
}

if (looksLikePlaceholder(config.businessName)) {
  errors.push('Set businessName to the name customers should see in messages.');
}

const timeZone = text(config.businessTimezone);
try {
  new Intl.DateTimeFormat('en-US', { timeZone }).format(new Date());
} catch (error) {
  errors.push('businessTimezone must be a valid IANA timezone such as Europe/Berlin.');
}

if (!text(config.reminderTemplateName)) {
  errors.push('Set reminderTemplateName to an existing Sent template name.');
}

const rescheduleUrl = text(config.rescheduleUrl);
if (looksLikePlaceholder(rescheduleUrl) || !/^https:\/\//i.test(rescheduleUrl)) {
  errors.push('Set rescheduleUrl to a real HTTPS booking or rescheduling URL.');
}

const firstHours = Number(config.firstReminderHours);
const finalHours = Number(config.finalReminderHours);
const catchupMinutes = Number(config.reminderCatchupMinutes);
const replySearchDays = Number(config.replySearchDays);

if (!(firstHours > finalHours && finalHours > 0)) {
  errors.push('firstReminderHours must be greater than finalReminderHours, and finalReminderHours must be greater than zero.');
}

if (!(catchupMinutes > 0)) {
  errors.push('reminderCatchupMinutes must be greater than zero.');
}

if (!(replySearchDays > 0)) {
  errors.push('replySearchDays must be greater than zero.');
}

if (typeof config.sandboxMode !== 'boolean') {
  errors.push('sandboxMode must be true or false.');
}

if (errors.length) {
  throw new Error('Complete Workflow Settings before running:\n- ' + errors.join('\n- '));
}

return [{ json: config }];
